        .toLowerCase()
        .replace(/[^\p{L}\p{N} _-]/gu, "")
        .replace(/ /g, "-");
    if (!seen) {
        return base;
    }
    const count = seen.get(base);
    if (count === undefined) {
        seen.set(base, 0);
        return base;
    }
    let n = count + 1;
    let slug = `${base}-${n}`;
